Codec.ejemplo:
class JsonCodec:
    def encode(self, data: dict) -> bytes:
        return json.dumps(data, separators=(",", ":")).encode("utf-8")
    def decode(self, raw: bytes) -> dict:
        return json.loads(raw.decode("utf-8"))

