MessagePack.ejemplo:
// Equivalente en bytes de {"ok": true, "n": 5}:
// JSON:        15 bytes -> {"ok":true,"n":5}
// MessagePack:  9 bytes -> 82 a2 6f 6b c3 a1 6e 05
import msgpack
raw = msgpack.packb({"ok": True, "n": 5})

Objetos cíclicos.ejemplo:
const a = { nombre: "A" };
a.self = a;
// JSON.stringify(a) -> TypeError: Converting circular structure to JSON
const seen = new WeakSet();
JSON.stringify(a, (_, v) => (typeof v === "object" && v !== null) ?
  (seen.has(v) ? "[Circular]" : (seen.add(v), v)) : v);

